<#
.SYNOPSIS
  Test the MSI validator (scripts/msi-validate.ps1) against MODIFIED copies of a valid MSI without installing anything.

.DESCRIPTION
  Starts with an MSI built by scripts/build-msi.ps1 (-Msi). Each case copies it to a dedicated %TEMP% directory, modifies
  the COPY through the Windows Installer API (opened for writing; this does not install anything or touch the original
  or system), and checks that the validator rejects it for the expected reason. Also checks that the valid MSI passes
  and that an API error is NOT mistaken for an empty table.

.PARAMETER Msi
  Path to a valid Tesela MSI (the one just generated by build-msi.ps1).

.EXAMPLE
  pwsh -File scripts/tests/msi-validate.tests.ps1 -Msi <target>/dist/tesela-0.1.0-x64.msi
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$Msi
)

$ErrorActionPreference = 'Stop'
. (Join-Path (Split-Path -Parent $PSScriptRoot) 'msi-validate.ps1')

$Msi = [System.IO.Path]::GetFullPath($Msi)
if (-not (Test-Path -LiteralPath $Msi -PathType Leaf)) { throw "MSI does not exist: $Msi" }

$failures = New-Object System.Collections.Generic.List[string]
$total = 0
function Check([string]$Case, [bool]$Condition) {
    $script:total++
    if (-not $Condition) { $script:failures.Add($Case) }
}

# Dedicated directory under %TEMP% (removed on exit only if it has the expected name).
$tmp = Join-Path ([System.IO.Path]::GetTempPath()) ('tesela-test-' + [guid]::NewGuid().ToString())
New-Item -ItemType Directory -Path $tmp | Out-Null

function Invoke-Sql($db, [string]$Sql) {
    # If a statement is invalid, report WHICH one (a malformed test case must not look like a validator failure).
    try {
        $view = [System.__ComObject].InvokeMember('OpenView', 'InvokeMethod', $null, $db, @($Sql))
        [System.__ComObject].InvokeMember('Execute', 'InvokeMethod', $null, $view, $null) | Out-Null
    } catch {
        throw "Invalid SQL statement: $Sql ($($_.Exception.Message))"
    }
    [System.__ComObject].InvokeMember('Close', 'InvokeMethod', $null, $view, $null) | Out-Null
    [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($view)
}

function New-Mutant([string]$Name, [string[]]$Statements) {
    # Copy the valid MSI, apply SQL statements, and return the copy's path.
    $path = Join-Path $tmp "$Name.msi"
    Copy-Item -LiteralPath $Msi -Destination $path
    $m = Open-MsiDatabase -Path $path -Write $true
    try {
        foreach ($s in $Statements) { Invoke-Sql $m.Db $s }
        [System.__ComObject].InvokeMember('Commit', 'InvokeMethod', $null, $m.Db, $null) | Out-Null
    } finally {
        Close-Msi $m
    }
    return $path
}

function New-WordCountMutant([string]$Name, [int]$Value) {
    # Copy the valid MSI and change the Summary Information word count (bit 8 = "no elevation required").
    $path = Join-Path $tmp "$Name.msi"
    Copy-Item -LiteralPath $Msi -Destination $path
    $m = Open-MsiDatabase -Path $path -Write $true
    try {
        $si = [System.__ComObject].InvokeMember('SummaryInformation', 'GetProperty', $null, $m.Db, @(1))
        [System.__ComObject].InvokeMember('Property', 'SetProperty', $null, $si, @(15, $Value)) | Out-Null
        [System.__ComObject].InvokeMember('Persist', 'InvokeMethod', $null, $si, $null) | Out-Null
        [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($si)
        [System.__ComObject].InvokeMember('Commit', 'InvokeMethod', $null, $m.Db, $null) | Out-Null
    } finally {
        Close-Msi $m
    }
    return $path
}

function Get-GoodVersion {
    $m = Open-MsiDatabase $Msi
    try {
        $r = @(Get-MsiRows $m 'SELECT `Value` FROM `Property` WHERE `Property`=''ProductVersion''' 1)
        return $r[0][0]
    } finally { Close-Msi $m }
}

function Has-Problem($Problems, [string]$Pattern) {
    return @($Problems | Where-Object { $_ -like $Pattern }).Count -gt 0
}

try {
    $version = Get-GoodVersion

    # --- The valid MSI passes -------------------------------------------------------------------------------------------
    $good = Test-MsiPackage -Path $Msi -ExpectedVersion $version
    Check "the valid MSI has no problems ($($good -join '; '))" ($good.Count -eq 0)

    # --- Each modification is rejected for its expected reason --------------------------------------------------------
    $p = Test-MsiPackage -Path $Msi -ExpectedVersion '9.9.9'
    Check 'different product version' (Has-Problem $p '*ProductVersion*')

    # --- Dual scope: per-user by default (ALLUSERS=2, MSIINSTALLPERUSER=1), without elevation ---------------------------
    $path = New-Mutant 'allusers1' @('UPDATE `Property` SET `Value`=''1'' WHERE `Property`=''ALLUSERS''')
    Check 'ALLUSERS=1 by default (per-machine)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*not per-user by default*')
    $path = New-Mutant 'allusers-none' @('DELETE FROM `Property` WHERE `Property`=''ALLUSERS''')
    Check 'missing ALLUSERS' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*not per-user by default*')
    $path = New-Mutant 'perusermode-none' @('DELETE FROM `Property` WHERE `Property`=''MSIINSTALLPERUSER''')
    Check 'missing MSIINSTALLPERUSER (ALLUSERS=2 alone would make it per-machine only for an administrator)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*not per-user by default*')
    $path = New-Mutant 'perusermode-0' @('UPDATE `Property` SET `Value`=''0'' WHERE `Property`=''MSIINSTALLPERUSER''')
    Check 'MSIINSTALLPERUSER=0' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*not per-user by default*')
    $path = New-WordCountMutant 'wordcount-bit8' 10
    Check 'with the "no elevation required" bit (the engine ignores MSIINSTALLPERUSER and a per-machine install would not require an administrator: 1925)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*declares*no elevation required*')
    $path = New-WordCountMutant 'wordcount-clean' 2
    Check 'word count 2 (without the bit) is valid' (-not (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*no elevation required*'))

    $path = New-Mutant 'upgradecode' @('UPDATE `Property` SET `Value`=''{11111111-2222-3333-4444-555555555555}'' WHERE `Property`=''UpgradeCode''')
    Check 'different UpgradeCode' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*UpgradeCode*')

    $path = New-Mutant 'unknown-property' @('INSERT INTO `Property` (`Property`, `Value`) VALUES (''EVILPROP'', ''x'')')
    Check 'a property outside the allowlist' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected property in the Property table*EVILPROP*')

    # --- Registry: HKMU\Software\Tesela only, with the eight expected values -------------------------------------------
    $path = New-Mutant 'hklm' @('INSERT INTO `Registry` (`Registry`, `Root`, `Key`, `Name`, `Value`, `Component_`) VALUES (''evilreg'', 2, ''Software\Evil'', ''n'', ''v'', ''TeselaExe'')')
    Check 'registry entry fixed to HKLM (not HKMU)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*registry entry outside HKMU*')
    $path = New-Mutant 'hkcu' @('UPDATE `Registry` SET `Root`=1 WHERE `Name`=''tesela.exe''')
    Check 'registry entry fixed to HKCU (not HKMU: a per-machine install would write to the user hive)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*registry entry outside HKMU*')
    $path = New-Mutant 'reg-otraclave' @('UPDATE `Registry` SET `Key`=''Software\Otra'' WHERE `Name`=''tesela.exe''')
    Check 'registry entry under a different key' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*registry entry outside HKMU*')
    $path = New-Mutant 'reg-valor' @('UPDATE `Registry` SET `Value`=''C:\Otra\'' WHERE `Name`=''InstallFolder''')
    Check 'InstallFolder with a different value' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*registry value InstallFolder*expected*[[]INSTALLFOLDER]*')
    $path = New-Mutant 'reg-extra' @('INSERT INTO `Registry` (`Registry`, `Root`, `Key`, `Name`, `Value`, `Component_`) VALUES (''extrareg'', -1, ''Software\Tesela'', ''Otro'', ''v'', ''TeselaExe'')')
    Check 'an extra registry value' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*writes 9 registry values*')
    $path = New-Mutant 'reg-nodesktop' @('DELETE FROM `Registry` WHERE `Name`=''DesktopShortcut''')
    Check 'missing the DesktopShortcut value (the desktop choice would not be remembered)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*registry value DesktopShortcut: found 0 rows*')

    $path = New-Mutant 'extrafile' @('INSERT INTO `File` (`File`, `Component_`, `FileName`, `FileSize`, `Sequence`) VALUES (''evil'', ''TeselaExe'', ''evil.exe'', 1, 99)')
    $p = Test-MsiPackage -Path $path -ExpectedVersion $version
    Check 'an extra file' ((Has-Problem $p '*unexpected file in the MSI*evil.exe*') -and (Has-Problem $p '*contains 6 files*'))

    # --- NO CODE: only the expected type 51 / 35 custom actions ---------------------------------------------------------
    $caCols = '`Action`, `Type`, `Source`, `Target`'
    $path = New-Mutant 'ca-dll' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('Evil', 1, 'Bin', 'x')")
    Check 'a type 1 custom action (DLL)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*custom action type 1*Evil*')
    $path = New-Mutant 'ca-exe' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('Evil', 2, 'Bin', 'x')")
    Check 'a type 2 custom action (EXE)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*custom action type 2*Evil*')
    $path = New-Mutant 'ca-script' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('Evil', 6, 'Bin', 'x')")
    Check 'a type 6 custom action (script)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*custom action type 6*Evil*')
    $path = New-Mutant 'ca-type34' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('Evil', 34, 'INSTALLFOLDER', 'x')")
    Check 'a type 34 custom action (EXE from a directory)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*custom action type 34*Evil*')
    $path = New-Mutant 'ca-type51-extra' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('Evil', 51, 'INSTALLFOLDER', 'C:\Evil')")
    Check 'a type 51 action outside the expected list' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected custom action*Evil*')
    $path = New-Mutant 'ca-type35-extra' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('Evil', 35, 'INSTALLFOLDER', 'C:\Evil')")
    Check 'a type 35 action outside the expected list' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected custom action*Evil*')
    $path = New-Mutant 'ca-target' @('UPDATE `CustomAction` SET `Target`=''[TESELA_PREV_MACHINE]'' WHERE `Action`=''TeselaFolderPrevUser''')
    Check 'an expected action with a different target' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*custom action TeselaFolderPrevUser*expected type 51*')
    $path = New-Mutant 'ca-source' @('UPDATE `CustomAction` SET `Source`=''ALLUSERS'' WHERE `Action`=''TeselaRememberDesktop''')
    Check 'an expected action on a different property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*custom action TeselaRememberDesktop*expected type 51*')
    $path = New-Mutant 'ca-missing' @('DELETE FROM `CustomAction` WHERE `Action`=''TeselaFolderDefaultUser''')
    Check 'a required action is missing' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing action TeselaFolderDefaultUser*')

    # Reject extra tables even when EMPTY: Environment, ServiceInstall, Class, Extension, ProgId, Binary, Error.
    $tables = [ordered]@{
        'Environment'    = 'CREATE TABLE `Environment` (`Environment` CHAR(72) NOT NULL, `Name` CHAR(255) NOT NULL, `Value` CHAR(255), `Component_` CHAR(72) NOT NULL PRIMARY KEY `Environment`)'
        'ServiceInstall' = 'CREATE TABLE `ServiceInstall` (`ServiceInstall` CHAR(72) NOT NULL, `Name` CHAR(255) NOT NULL, `Component_` CHAR(72) NOT NULL PRIMARY KEY `ServiceInstall`)'
        'Class'          = 'CREATE TABLE `Class` (`CLSID` CHAR(38) NOT NULL, `Context` CHAR(32) NOT NULL, `Component_` CHAR(72) NOT NULL PRIMARY KEY `CLSID`, `Context`)'
        'Extension'      = 'CREATE TABLE `Extension` (`Extension` CHAR(255) NOT NULL, `Component_` CHAR(72) NOT NULL PRIMARY KEY `Extension`, `Component_`)'
        'ProgId'         = 'CREATE TABLE `ProgId` (`ProgId` CHAR(255) NOT NULL, `Description` CHAR(255) PRIMARY KEY `ProgId`)'
        'Binary'         = 'CREATE TABLE `Binary` (`Name` CHAR(72) NOT NULL, `Data` OBJECT NOT NULL PRIMARY KEY `Name`)'
        'Error'          = 'CREATE TABLE `Error` (`Error` SHORT NOT NULL, `Message` CHAR(255) LOCALIZABLE PRIMARY KEY `Error`)'
        'Billboard'      = 'CREATE TABLE `Billboard` (`Billboard` CHAR(50) NOT NULL, `Feature_` CHAR(38) NOT NULL PRIMARY KEY `Billboard`)'
    }
    foreach ($t in $tables.Keys) {
        $path = New-Mutant ('table-' + $t) @($tables[$t])
        Check "extra empty table: $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*table not allowed*$t*")
    }

    $path = New-Mutant 'noshortcut' @('DELETE FROM `Shortcut`')
    Check 'no shortcuts' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly 2 shortcuts*')
    $path = New-Mutant 'nodesktopshortcut' @('DELETE FROM `Shortcut` WHERE `Shortcut`=''DesktopShortcut''')
    Check 'missing the desktop shortcut' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*shortcut DesktopShortcut*DesktopFolder*')
    $path = New-Mutant 'desktopshortcut-dir' @('UPDATE `Shortcut` SET `Directory_`=''ProgramMenuFolder'' WHERE `Shortcut`=''DesktopShortcut''')
    Check 'desktop shortcut in the Start menu' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*shortcut DesktopShortcut*DesktopFolder*')

    # --- Registry searches for previous installs (four, HKCU and HKLM) --------------------------------------------------
    $path = New-Mutant 'nosearch' @('DELETE FROM `AppSearch`')
    Check 'missing the previous-install searches' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*AppSearch*')
    $path = New-Mutant 'nosearch-machine' @('DELETE FROM `AppSearch` WHERE `Property`=''TESELA_PREV_MACHINE''')
    Check 'missing the per-machine installation search (the scope-change block would not detect it)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TESELA_PREV_MACHINE*')
    $path = New-Mutant 'reglocator-type2' @('UPDATE `RegLocator` SET `Type`=2')
    Check 'RegLocator with Type=2 (32-bit view) instead of 18' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected ONE registry search*type 18*')
    $path = New-Mutant 'reglocator-root' @('UPDATE `RegLocator` SET `Root`=1 WHERE `Signature_`=''PrevMachineFolder''')
    Check 'per-machine installation search looks in HKCU' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*PrevMachineFolder*root 2*')
    $path = New-Mutant 'reglocator-name' @('UPDATE `RegLocator` SET `Name`=''Otro'' WHERE `Signature_`=''PrevUserFolder''')
    Check 'a search with a different value name' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*PrevUserFolder*')

    # --- RemoveFile: one row only (INSTALLFOLDER, if empty) -------------------------------------------------------------
    $path = New-Mutant 'removefile-extra' @('INSERT INTO `RemoveFile` (`FileKey`, `Component_`, `FileName`, `DirProperty`, `InstallMode`) VALUES (''evilrm'', ''TeselaExe'', ''*.*'', ''INSTALLFOLDER'', 2)')
    $p = Test-MsiPackage -Path $path -ExpectedVersion $version
    Check 'an extra RemoveFile row (with *.*)' ((Has-Problem $p '*unexpected RemoveFile row*evilrm*') -and (Has-Problem $p '*RemoveFile must have exactly 1 row*'))
    $path = New-Mutant 'removefile-otradir' @('UPDATE `RemoveFile` SET `DirProperty`=''ProgramMenuFolder'' WHERE `FileKey`=''RemoveInstallFolder''')
    Check 'RemoveFile targets a different directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected RemoveFile row*')
    $path = New-Mutant 'removefile-none' @('DELETE FROM `RemoveFile`')
    Check 'missing RemoveFile (the installation directory would remain after uninstall)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*RemoveFile must have exactly 1 row*')

    # --- EXACT directory tree (Directory_Parent and DefaultDir) ----------------------------------------------------------
    foreach ($case in @(
            @('INSTALLFOLDER under ProgramMenuFolder (wrong parent)', 'INSTALLFOLDER', "UPDATE ``Directory`` SET ``Directory_Parent``='ProgramMenuFolder' WHERE ``Directory``='INSTALLFOLDER'", '*directory INSTALLFOLDER*Directory_Parent*TARGETDIR*'),
            @('INSTALLFOLDER without a parent', 'INSTALLFOLDER', "UPDATE ``Directory`` SET ``Directory_Parent``='' WHERE ``Directory``='INSTALLFOLDER'", '*directory INSTALLFOLDER*Directory_Parent*TARGETDIR*'),
            @('ProgramMenuFolder under INSTALLFOLDER', 'ProgramMenuFolder', "UPDATE ``Directory`` SET ``Directory_Parent``='INSTALLFOLDER' WHERE ``Directory``='ProgramMenuFolder'", '*directory ProgramMenuFolder*Directory_Parent*TARGETDIR*'),
            @('DesktopFolder under INSTALLFOLDER', 'DesktopFolder', "UPDATE ``Directory`` SET ``Directory_Parent``='INSTALLFOLDER' WHERE ``Directory``='DesktopFolder'", '*directory DesktopFolder*Directory_Parent*TARGETDIR*'),
            @('TARGETDIR with a parent', 'TARGETDIR', "UPDATE ``Directory`` SET ``Directory_Parent``='INSTALLFOLDER' WHERE ``Directory``='TARGETDIR'", '*directory TARGETDIR*Directory_Parent*'),
            @('INSTALLFOLDER with a different name (DefaultDir)', 'INSTALLFOLDER', "UPDATE ``Directory`` SET ``DefaultDir``='OtraCarpeta' WHERE ``Directory``='INSTALLFOLDER'", '*directory INSTALLFOLDER*DefaultDir*Tesela*')
        )) {
        $path = New-Mutant ('dir-' + $case[1] + '-' + [guid]::NewGuid().ToString('N').Substring(0, 6)) @($case[2])
        Check ('directories: ' + $case[0]) (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) $case[3])
    }
    # DefaultDir may use "short|long": accept it when the long name matches.
    $path = New-Mutant 'dir-shortlong' @("UPDATE ``Directory`` SET ``DefaultDir``='Tesela|Tesela' WHERE ``Directory``='INSTALLFOLDER'")
    Check 'directories: short|long DefaultDir with the expected long name is valid' (-not (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*DefaultDir*'))
    $path = New-Mutant 'dir-extra' @("INSERT INTO ``Directory`` (``Directory``, ``Directory_Parent``, ``DefaultDir``) VALUES ('EvilDir', 'TARGETDIR', 'Evil')")
    Check 'directories: an extra directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected directory*EvilDir*')
    $path = New-Mutant 'dir-programfiles' @("INSERT INTO ``Directory`` (``Directory``, ``Directory_Parent``, ``DefaultDir``) VALUES ('ProgramFiles64Folder', 'TARGETDIR', '.')")
    Check 'directories: ProgramFiles64Folder fixed in the tree (the action, not the tree, determines scope)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected directory*ProgramFiles64Folder*')
    $path = New-Mutant 'dir-missing' @("DELETE FROM ``Directory`` WHERE ``Directory``='DesktopFolder'")
    Check 'directories: an expected directory is missing' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*directory DesktopFolder*0 rows*')

    # --- Components: directory, attributes, and desktop condition -------------------------------------------------------
    $path = New-Mutant 'component-nocond' @('UPDATE `Component` SET `Condition`='''' WHERE `Component`=''DesktopShortcut''')
    Check 'desktop shortcut without a condition (it would always be created)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component DesktopShortcut*Condition*DESKTOPSHORTCUT*')
    $path = New-Mutant 'component-cond-exe' @('UPDATE `Component` SET `Condition`=''DESKTOPSHORTCUT="1"'' WHERE `Component`=''TeselaExe''')
    Check 'tesela.exe with a condition (it would not be installed unless the checkbox is selected)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component TeselaExe*Condition*')
    $path = New-Mutant 'component-dir' @('UPDATE `Component` SET `Directory_`=''DesktopFolder'' WHERE `Component`=''TeselaExe''')
    Check 'tesela.exe in the desktop directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component TeselaExe is in DesktopFolder*')
    $path = New-Mutant 'component-attr' @('UPDATE `Component` SET `Attributes`=4 WHERE `Component`=''TeselaExe''')
    Check '32-bit component' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component TeselaExe*Attributes*260*')

    # --- MajorUpgrade and newer-version block: exact values -------------------------------------------------------------
    $upgCodeValue = '{7E8F4B67-A7D4-415B-9F8F-2E0B88AA88BB}'
    $upCols = '`UpgradeCode`, `VersionMin`, `VersionMax`, `Language`, `Attributes`, `Remove`, `ActionProperty`'
    $delDown = "DELETE FROM ``Upgrade`` WHERE ``ActionProperty``='WIX_DOWNGRADE_DETECTED'"
    $delUp = "DELETE FROM ``Upgrade`` WHERE ``ActionProperty``='WIX_UPGRADE_DETECTED'"
    function Down-Row([string]$Min, [string]$Lang, [int]$Attr, [string]$Prop = 'WIX_DOWNGRADE_DETECTED', [string]$UCode = $upgCodeValue) {
        return "INSERT INTO ``Upgrade`` ($upCols) VALUES ('$UCode', '$Min', '', '$Lang', $Attr, '', '$Prop')"
    }
    function Up-Row([string]$Max, [string]$Lang, [int]$Attr, [string]$Prop = 'WIX_UPGRADE_DETECTED') {
        return "INSERT INTO ``Upgrade`` ($upCols) VALUES ('$upgCodeValue', '', '$Max', '$Lang', $Attr, '', '$Prop')"
    }
    # Control: restoring both rows exactly with these helpers produces a valid MSI (the mutations below are reliable).
    $path = New-Mutant 'upgrade-control' @($delDown, $delUp, (Down-Row $version '1033' 2), (Up-Row $version '1033' 513))
    Check 'Upgrade: restoring both rows exactly is still valid' ((Test-MsiPackage -Path $path -ExpectedVersion $version).Count -eq 0)

    $path = New-Mutant 'upgrade-nodown' @($delDown)
    Check 'Upgrade: the newer-version blocking row is missing' ((Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing Upgrade row*bloquear*WIX_DOWNGRADE_DETECTED*') -and (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Upgrade table has 1 rows*'))
    $path = New-Mutant 'upgrade-noup' @($delUp)
    Check 'Upgrade: the older-version replacement row is missing' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing Upgrade row*reemplazar*WIX_UPGRADE_DETECTED*')
    $path = New-Mutant 'upgrade-noneatall' @($delDown, $delUp)
    Check 'Upgrade: no MajorUpgrade (empty table)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Upgrade table has 0 rows*')
    $path = New-Mutant 'upgrade-down-attr0' @($delDown, (Down-Row $version '1033' 0))
    Check 'Upgrade: blocking row without OnlyDetect (Attributes = 0: would uninstall the newer version)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*bloquear*Attributes = ''0''*expected ''2''*')
    $path = New-Mutant 'upgrade-down-attr258' @($delDown, (Down-Row $version '1033' 258))
    Check 'Upgrade: blocking row with inclusive VersionMin (Attributes = 258)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*bloquear*Attributes = ''258''*')
    $path = New-Mutant 'upgrade-up-attr1' @($delUp, (Up-Row $version '1033' 1))
    Check 'Upgrade: replacement row without inclusive VersionMax (Attributes = 1)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*reemplazar*Attributes = ''1''*expected ''513''*')
    $path = New-Mutant 'upgrade-up-attr512' @($delUp, (Up-Row $version '1033' 512))
    Check 'Upgrade: replacement row without MigrateFeatures (Attributes = 512)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*reemplazar*Attributes = ''512''*')
    $path = New-Mutant 'upgrade-down-min' @($delDown, (Down-Row '0.0.1' '1033' 2))
    Check 'Upgrade: blocking row with a different VersionMin' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*bloquear*VersionMin = ''0.0.1''*')
    $path = New-Mutant 'upgrade-up-max' @($delUp, (Up-Row '99.0.0' '1033' 513))
    Check 'Upgrade: replacement row with a different VersionMax' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*reemplazar*VersionMax = ''99.0.0''*')
    $path = New-Mutant 'upgrade-down-lang' @($delDown, (Down-Row $version '3082' 2))
    Check 'Upgrade: blocking row with a different language' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*bloquear*Language = ''3082''*')
    $path = New-Mutant 'upgrade-down-prop' @($delDown, (Down-Row $version '1033' 2 'OTRA_PROPIEDAD'))
    Check 'Upgrade: blocking row with a different ActionProperty' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing Upgrade row*WIX_DOWNGRADE_DETECTED*')
    $path = New-Mutant 'upgrade-down-code' @($delDown, (Down-Row $version '1033' 2 'WIX_DOWNGRADE_DETECTED' '{11111111-2222-3333-4444-555555555555}'))
    Check 'Upgrade: blocking row with a different UpgradeCode' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*bloquear*UpgradeCode*')
    $path = New-Mutant 'upgrade-extra' @((Down-Row '0.0.1' '1033' 2 'OTRA_PROPIEDAD'))
    Check 'Upgrade: an extra row' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Upgrade table has 3 rows*')
    # With a different expected version, VersionMin/VersionMax no longer match.
    $p = Test-MsiPackage -Path $Msi -ExpectedVersion '9.9.9'
    Check 'Upgrade: a different expected version (VersionMax and VersionMin follow the product version)' ((Has-Problem $p '*reemplazar*VersionMax*9.9.9*') -and (Has-Problem $p '*bloquear*VersionMin*9.9.9*'))

    # --- LaunchCondition: exactly FOUR, each with a message (Condition is the primary key: delete and insert) ------------
    $lcMsg = 'Mensaje de prueba'
    $path = New-Mutant 'lc-nonot' @("DELETE FROM ``LaunchCondition`` WHERE ``Condition``='NOT WIX_DOWNGRADE_DETECTED'", "INSERT INTO ``LaunchCondition`` (``Condition``, ``Description``) VALUES ('WIX_DOWNGRADE_DETECTED', '$lcMsg')")
    Check 'LaunchCondition without NOT (it would block users who are NOT installing over an older version)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*NOT WIX_DOWNGRADE_DETECTED*')
    $path = New-Mutant 'lc-other' @("DELETE FROM ``LaunchCondition`` WHERE ``Condition``='NOT WIX_DOWNGRADE_DETECTED'", "INSERT INTO ``LaunchCondition`` (``Condition``, ``Description``) VALUES ('NOT WIX_UPGRADE_DETECTED', '$lcMsg')")
    Check 'LaunchCondition on a different property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')
    $path = New-Mutant 'lc-none' @("DELETE FROM ``LaunchCondition``")
    Check 'missing LaunchCondition' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')
    $path = New-Mutant 'lc-extra' @("INSERT INTO ``LaunchCondition`` (``Condition``, ``Description``) VALUES ('1=1', '$lcMsg')")
    Check 'an extra LaunchCondition' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')
    $path = New-Mutant 'lc-nomsg' @('UPDATE `LaunchCondition` SET `Description`='' '' WHERE `Condition`=''NOT WIX_DOWNGRADE_DETECTED''')
    Check 'LaunchCondition with a blank message' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*LaunchCondition*has no message*')
    # The three scope checks: remove any one (Condition is the key; delete by exact value because MSI SQL has no LIKE).
    $lcScope = @(
        @('scope change from per-user to per-machine', $MsiExpectedLaunchConditions[1]),
        @('scope change from per-machine to per-user', $MsiExpectedLaunchConditions[2]),
        @('protected directory in a per-user installation', $MsiExpectedLaunchConditions[3]),
        @('path format (absolute, without /, .., ?, or a network path)', $MsiExpectedLaunchConditions[4])
    )
    foreach ($c in $lcScope) {
        $path = New-Mutant ('lc-del-' + [guid]::NewGuid().ToString('N').Substring(0, 6)) @("DELETE FROM ``LaunchCondition`` WHERE ``Condition``='$($c[1])'")
        Check ('missing the LaunchCondition for ' + $c[0]) (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')
    }
    # M2: without "OR TESELA_PREV_USER<>""", this user's per-user installation would lose to another account's.
    $noOwn = $MsiExpectedLaunchConditions[2].Replace(' OR TESELA_PREV_USER<>""', '')
    $path = New-Mutant 'lc-noown' @("DELETE FROM ``LaunchCondition`` WHERE ``Condition``='$($MsiExpectedLaunchConditions[2])'", "INSERT INTO ``LaunchCondition`` (``Condition``, ``Description``) VALUES ('$noOwn', '$lcMsg')")
    Check 'LaunchCondition for machine installation also blocks an owner of a per-user installation (M2)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')
    # The condition must allow the full UI and repairs; without "UILevel>=5" it is no longer exact.
    $noUi = $MsiExpectedLaunchConditions[1].Replace(' OR UILevel>=5', '')
    $path = New-Mutant 'lc-nouilevel' @("DELETE FROM ``LaunchCondition`` WHERE ``Condition``='$($MsiExpectedLaunchConditions[1])'", "INSERT INTO ``LaunchCondition`` (``Condition``, ``Description``) VALUES ('$noUi', '$lcMsg')")
    Check 'scope-change LaunchCondition without allowing the full UI' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')

    # Ensure these checks TAKE EFFECT: their actions must exist, be unconditional, and be correctly sequenced.
    $path = New-Mutant 'seq-noremove' @("DELETE FROM ``InstallExecuteSequence`` WHERE ``Action``='RemoveExistingProducts'")
    Check 'missing RemoveExistingProducts in InstallExecuteSequence' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*RemoveExistingProducts is missing*')
    $path = New-Mutant 'seq-removecond' @("UPDATE ``InstallExecuteSequence`` SET ``Condition``='0' WHERE ``Action``='RemoveExistingProducts'")
    Check 'RemoveExistingProducts with a condition' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*RemoveExistingProducts has condition*')
    $path = New-Mutant 'seq-removelate' @("UPDATE ``InstallExecuteSequence`` SET ``Sequence``=6500 WHERE ``Action``='RemoveExistingProducts'")
    Check 'RemoveExistingProducts outside InstallValidate..InstallInitialize' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*RemoveExistingProducts*between InstallValidate and InstallInitialize*')
    foreach ($t in 'InstallExecuteSequence', 'InstallUISequence') {
        foreach ($a in 'FindRelatedProducts', 'LaunchConditions') {
            $path = New-Mutant "seq-no-$a-$t" @("DELETE FROM ``$t`` WHERE ``Action``='$a'")
            Check "missing $a in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*missing $a in $t*")
            $path = New-Mutant "seq-cond-$a-$t" @("UPDATE ``$t`` SET ``Condition``='0' WHERE ``Action``='$a'")
            Check "$a has a condition in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*$a in $t has condition*")
        }
    }
    # FindRelatedProducts must precede LaunchConditions in both sequences; otherwise the property is empty when the
    # condition is evaluated, so the block does nothing even when all rows are present.
    foreach ($t in 'InstallExecuteSequence', 'InstallUISequence') {
        $path = New-Mutant "seq-order-frp-after-$t" @("UPDATE ``$t`` SET ``Sequence``=200 WHERE ``Action``='FindRelatedProducts'")
        Check "FindRelatedProducts (200) after LaunchConditions (100) in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*FindRelatedProducts*must run before LaunchConditions*$t*")
        $path = New-Mutant "seq-order-lc-before-$t" @("UPDATE ``$t`` SET ``Sequence``=10 WHERE ``Action``='LaunchConditions'")
        Check "LaunchConditions (10) before FindRelatedProducts (25) in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*FindRelatedProducts*must run before LaunchConditions*$t*")
        $path = New-Mutant "seq-order-equal-$t" @("UPDATE ``$t`` SET ``Sequence``=100 WHERE ``Action``='FindRelatedProducts'")
        Check "FindRelatedProducts and LaunchConditions with the same sequence number in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*FindRelatedProducts*must run before LaunchConditions*$t*")
    }

    # Identifiers and properties are CASE-SENSITIVE (Windows Installer behaves this way).
    $path = New-Mutant 'case-parent' @("UPDATE ``Directory`` SET ``Directory_Parent``='targetdir' WHERE ``Directory``='INSTALLFOLDER'")
    Check 'Directory_Parent in lowercase (targetdir)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*directory INSTALLFOLDER*Directory_Parent*')
    $path = New-Mutant 'case-actionproperty' @($delDown, (Down-Row $version '1033' 2 'wix_downgrade_detected'))
    Check 'blocking ActionProperty in lowercase (wix_downgrade_detected)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing Upgrade row*WIX_DOWNGRADE_DETECTED*')
    $path = New-Mutant 'case-launchcondition' @("DELETE FROM ``LaunchCondition`` WHERE ``Condition``='NOT WIX_DOWNGRADE_DETECTED'", "INSERT INTO ``LaunchCondition`` (``Condition``, ``Description``) VALUES ('NOT wix_downgrade_detected', '$lcMsg')")
    Check 'LaunchCondition with the property in lowercase' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected exactly these 5 LaunchConditions*')
    $path = New-Mutant 'case-secure' @("UPDATE ``Property`` SET ``Value``='DESKTOPSHORTCUT;INSTALLFOLDER;wix_upgrade_detected;wix_downgrade_detected' WHERE ``Property``='SecureCustomProperties'")
    Check 'SecureCustomProperties in lowercase' ((Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties does not include WIX_DOWNGRADE_DETECTED*') -and (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties does not include WIX_UPGRADE_DETECTED*'))

    # --- Secure properties: EXACTLY the expected set (INSTALLFOLDER and DESKTOPSHORTCUT must be secure) ------------------
    $secureAll = 'DESKTOPSHORTCUT;INSTALLFOLDER;WIX_DOWNGRADE_DETECTED;WIX_UPGRADE_DETECTED'
    $path = New-Mutant 'secure-no-installfolder' @("UPDATE ``Property`` SET ``Value``='DESKTOPSHORTCUT;WIX_DOWNGRADE_DETECTED;WIX_UPGRADE_DETECTED' WHERE ``Property``='SecureCustomProperties'")
    Check 'INSTALLFOLDER is not a secure property (an elevated per-machine install would ignore it)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties does not include INSTALLFOLDER*')
    $path = New-Mutant 'secure-no-desktop' @("UPDATE ``Property`` SET ``Value``='INSTALLFOLDER;WIX_DOWNGRADE_DETECTED;WIX_UPGRADE_DETECTED' WHERE ``Property``='SecureCustomProperties'")
    Check 'DESKTOPSHORTCUT is not a secure property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties does not include DESKTOPSHORTCUT*')
    $path = New-Mutant 'secure-allusers' @("UPDATE ``Property`` SET ``Value``='$secureAll;ALLUSERS' WHERE ``Property``='SecureCustomProperties'")
    Check 'ALLUSERS marked as a secure property (it is always passed to the server; this is unnecessary)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties includes ALLUSERS*')
    $path = New-Mutant 'secure-peruser' @("UPDATE ``Property`` SET ``Value``='$secureAll;MSIINSTALLPERUSER' WHERE ``Property``='SecureCustomProperties'")
    Check 'MSIINSTALLPERUSER marked as a secure property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties includes MSIINSTALLPERUSER*')
    $path = New-Mutant 'secure-extra' @("UPDATE ``Property`` SET ``Value``='$secureAll;TESELA_LANG' WHERE ``Property``='SecureCustomProperties'")
    Check 'an extra secure property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties includes TESELA_LANG*')
    $path = New-Mutant 'secure-props' @("UPDATE ``Property`` SET ``Value``='WIX_UPGRADE_DETECTED' WHERE ``Property``='SecureCustomProperties'")
    Check 'SecureCustomProperties missing WIX_DOWNGRADE_DETECTED' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SecureCustomProperties does not include WIX_DOWNGRADE_DETECTED*')
    $path = New-Mutant 'default-installfolder' @('INSERT INTO `Property` (`Property`, `Value`) VALUES (''INSTALLFOLDER'', ''C:\Fija\'')')
    Check 'INSTALLFOLDER has a default value in the Property table (it would override the scope-based calculation)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*property INSTALLFOLDER has a default value*')
    $path = New-Mutant 'default-desktop' @('INSERT INTO `Property` (`Property`, `Value`) VALUES (''DESKTOPSHORTCUT'', ''1'')')
    Check 'DESKTOPSHORTCUT enabled by default' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*property DESKTOPSHORTCUT has a default value*')
    $path = New-Mutant 'default-scope' @('UPDATE `Property` SET `Value`=''machine'' WHERE `Property`=''TESELA_SCOPE''')
    Check 'the dialog scope defaults to per-machine' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TESELA_SCOPE default*user*')

    # --- Shortcuts: no arguments and the install directory as working directory -----------------------------------------
    $path = New-Mutant 'shortcut-args' @("UPDATE ``Shortcut`` SET ``Arguments``='--demo'")
    Check 'shortcut with arguments' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*shortcut*has arguments*--demo*')
    $path = New-Mutant 'shortcut-args-desktop' @("UPDATE ``Shortcut`` SET ``Arguments``='--demo' WHERE ``Shortcut``='DesktopShortcut'")
    Check 'desktop shortcut with arguments' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*DesktopShortcut has arguments*--demo*')
    $path = New-Mutant 'shortcut-wkdir' @("UPDATE ``Shortcut`` SET ``WkDir``='ProgramMenuFolder'")
    Check 'shortcut with a different working directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*WkDir*ProgramMenuFolder*INSTALLFOLDER*')
    $path = New-Mutant 'shortcut-nowkdir' @("UPDATE ``Shortcut`` SET ``WkDir``=''")
    Check 'shortcut without a working directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*WkDir*expected*INSTALLFOLDER*')

    # --- Fixed component GUIDs -------------------------------------------------------------------------------------------
    $path = New-Mutant 'component-guid' @("UPDATE ``Component`` SET ``ComponentId``='{11111111-2222-3333-4444-555555555555}' WHERE ``Component``='StartMenuShortcut'")
    Check 'different GUID in the shortcut component' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component StartMenuShortcut*GUID*')
    $path = New-Mutant 'component-guid-exe' @("UPDATE ``Component`` SET ``ComponentId``='{11111111-2222-3333-4444-555555555555}' WHERE ``Component``='TeselaExe'")
    Check 'different GUID in the tesela.exe component' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component TeselaExe*GUID*')
    $path = New-Mutant 'component-guid-desktop' @("UPDATE ``Component`` SET ``ComponentId``='{11111111-2222-3333-4444-555555555555}' WHERE ``Component``='DesktopShortcut'")
    Check 'different GUID in the desktop shortcut component' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*component DesktopShortcut*GUID*')

    # --- AppSearch: action is unconditional and precedes CostFinalize in both sequences; empty Signature ------------------
    foreach ($t in 'InstallExecuteSequence', 'InstallUISequence') {
        $path = New-Mutant "appsearch-none-$t" @("DELETE FROM ``$t`` WHERE ``Action``='AppSearch'")
        Check "missing AppSearch in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*missing AppSearch in $t*")
        $path = New-Mutant "appsearch-cond-$t" @("UPDATE ``$t`` SET ``Condition``='0' WHERE ``Action``='AppSearch'")
        Check "AppSearch has a condition in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*AppSearch in $t has condition*")
        $path = New-Mutant "appsearch-late-$t" @("UPDATE ``$t`` SET ``Sequence``=2000 WHERE ``Action``='AppSearch'")
        Check "AppSearch after CostFinalize in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*AppSearch*must run before CostFinalize*$t*")
    }
    $sigStatements = @('INSERT INTO `Signature` (`Signature`, `FileName`) VALUES (''EvilSearch'', ''evil.dll'')')
    $path = New-Mutant 'signature-row' $sigStatements
    Check 'a row in the Signature table (undeclared file search)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Signature table has 3 rows*exactly 2*')

    # --- Sequence rows for scope, directory, and language logic ----------------------------------------------------------
    foreach ($t in 'InstallExecuteSequence', 'InstallUISequence') {
        $path = New-Mutant "logic-nofolder-$t" @("DELETE FROM ``$t`` WHERE ``Action``='TeselaFolderPrevUser'")
        Check "missing TeselaFolderPrevUser in $t (an upgrade would not preserve the directory)" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*missing TeselaFolderPrevUser in $t*")
        $path = New-Mutant "logic-cond-$t" @("UPDATE ``$t`` SET ``Condition``='1' WHERE ``Action``='TeselaFolderDefaultMachine'")
        Check "TeselaFolderDefaultMachine with a different condition in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*TeselaFolderDefaultMachine in $t has condition*")
        $path = New-Mutant "logic-seq-$t" @("UPDATE ``$t`` SET ``Sequence``=105 WHERE ``Action``='TeselaSetProtected64'")
        $p = Test-MsiPackage -Path $path -ExpectedVersion $version
        Check "TeselaSetProtected64 after LaunchConditions in $t" ((Has-Problem $p "*TeselaSetProtected64 in $t has sequence 105*") -and (Has-Problem $p '*TeselaSetProtected64*after AppSearch and before LaunchConditions*'))
        $path = New-Mutant "logic-beforesearch-$t" @("UPDATE ``$t`` SET ``Sequence``=40 WHERE ``Action``='TeselaFolderPrevMachine'")
        Check "TeselaFolderPrevMachine before AppSearch in $t" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaFolderPrevMachine*after AppSearch and before LaunchConditions*')
    }
    $path = New-Mutant 'logic-desktop-exec' @("UPDATE ``InstallExecuteSequence`` SET ``Condition``='DESKTOPSHORTCUT=""""' WHERE ``Action``='TeselaRememberDesktop'")
    Check 'TeselaRememberDesktop in the server sequence without the UILevel guard (it would reselect a checkbox the user cleared)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaRememberDesktop in InstallExecuteSequence has condition*')
    $path = New-Mutant 'logic-scope-exec' @("INSERT INTO ``InstallExecuteSequence`` (``Action``, ``Condition``, ``Sequence``) VALUES ('TeselaLangEs1', '', 62)")
    Check 'the selected language is also in the server sequence' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaLangEs1 is in InstallExecuteSequence*')
    $path = New-Mutant 'lang-missing-id' @("UPDATE ``InstallUISequence`` SET ``Condition``='TESELA_LANG="""" AND (UserLanguageID=9226 OR UserLanguageID=10250)' WHERE ``Action``='TeselaLangEs2'")
    Check 'the language actions do not cover all Spanish LANGIDs' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaLangEs1..3 do not cover exactly the Spanish LANGIDs*')
    $path = New-Mutant 'lang-extra-id' @("UPDATE ``InstallUISequence`` SET ``Condition``='TESELA_LANG="""" AND (UserLanguageID=1033)' WHERE ``Action``='TeselaLangEs3'")
    Check 'a language action with a non-Spanish LANGID (1033)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaLangEs1..3 do not cover exactly the Spanish LANGIDs*')

    # --- UI strings: every English Tx* has a Spanish counterpart and is displayed ---------------------------------------
    $path = New-Mutant 'tx-no-es' @('DELETE FROM `CustomAction` WHERE `Action`=''TeselaEs_TxNext''')
    Check 'text without a Spanish version' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*text TxNext has no Spanish version*')
    $path = New-Mutant 'tx-no-seqrow' @('DELETE FROM `InstallUISequence` WHERE `Action`=''TeselaEs_TxNext''')
    Check 'Spanish text without a sequence row' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing TeselaEs_TxNext in InstallUISequence*')
    $path = New-Mutant 'tx-bad-cond' @('UPDATE `InstallUISequence` SET `Condition`=''1'' WHERE `Action`=''TeselaEs_TxNext''')
    Check 'Spanish text that always applies (without TESELA_LANG="es")' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaEs_TxNext in InstallUISequence has condition*')
    $path = New-Mutant 'tx-in-exec' @("INSERT INTO ``InstallExecuteSequence`` (``Action``, ``Condition``, ``Sequence``) VALUES ('TeselaEs_TxNext', '', 63)")
    Check 'Spanish text in the server sequence' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaEs_TxNext is in InstallExecuteSequence*')
    $path = New-Mutant 'tx-bad-seq' @('UPDATE `InstallUISequence` SET `Sequence`=1500 WHERE `Action`=''TeselaEs_TxNext''')
    Check 'Spanish text after the dialogs' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaEs_TxNext*before the dialogs*')
    $path = New-Mutant 'tx-brackets' @('UPDATE `Property` SET `Value`=''Siguiente [INSTALLFOLDER]'' WHERE `Property`=''TxNext''')
    Check 'text containing a property (it is not formatted again)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*text TxNext contains brackets*')
    $path = New-Mutant 'tx-es-brackets' @('UPDATE `CustomAction` SET `Target`=''Siguiente [INSTALLFOLDER]'' WHERE `Action`=''TeselaEs_TxNext''')
    Check 'Spanish text containing a property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Spanish text for TxNext contains brackets*')
    $path = New-Mutant 'tx-es-empty' @('UPDATE `CustomAction` SET `Target`='' '' WHERE `Action`=''TeselaEs_TxNext''')
    Check 'empty Spanish text' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*TeselaEs_TxNext must be type 51*have text*')
    $path = New-Mutant 'tx-orphan' @('INSERT INTO `Property` (`Property`, `Value`) VALUES (''TxHuerfano'', ''Texto'')')
    $p = Test-MsiPackage -Path $path -ExpectedVersion $version
    Check 'text not shown in any dialog' ((Has-Problem $p '*text TxHuerfano is not shown in any dialog*') -and (Has-Problem $p '*text TxHuerfano has no Spanish version*'))
    $path = New-Mutant 'tx-es-orphan' @("INSERT INTO ``CustomAction`` ($caCols) VALUES ('TeselaEs_TxSinIngles', 51, 'TxSinIngles', 'Texto')")
    Check 'a text action without an English property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*text action has no English property*TeselaEs_TxSinIngles*')
    $path = New-Mutant 'tx-missing' @('UPDATE `Control` SET `Text`=''[TxNoExiste]'' WHERE `Dialog_`=''WelcomeDlg'' AND `Control`=''Body''')
    Check 'a dialog displays text that does not exist' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*displays text [[]TxNoExiste]*missing from the Property table*')

    # --- UI: dialogs, controls without images, and native events only ---------------------------------------------------
    $path = New-Mutant 'ui-extra-dialog' @('INSERT INTO `Dialog` (`Dialog`, `HCentering`, `VCentering`, `Width`, `Height`, `Attributes`, `Title`, `Control_First`) VALUES (''EvilDlg'', 50, 50, 100, 100, 3, ''x'', ''Ok'')')
    Check 'an extra dialog' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected dialog*EvilDlg*')
    $path = New-Mutant 'ui-missing-dialog' @('DELETE FROM `Dialog` WHERE `Dialog`=''InvalidDirDlg''')
    Check 'a dialog is missing' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing dialog InvalidDirDlg*')
    $path = New-Mutant 'ui-bitmap' @('UPDATE `Control` SET `Type`=''Bitmap'' WHERE `Dialog_`=''WelcomeDlg'' AND `Control`=''Body''')
    Check 'an image control (requires Binary)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*control not allowed*WelcomeDlg.Body*Bitmap*')
    $path = New-Mutant 'ui-icon' @('UPDATE `Control` SET `Type`=''Icon'' WHERE `Dialog_`=''WelcomeDlg'' AND `Control`=''Body''')
    Check 'an icon control' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*control not allowed*WelcomeDlg.Body*Icon*')
    $evCols = '`Dialog_`, `Control_`, `Event`, `Argument`, `Condition`, `Ordering`'
    $path = New-Mutant 'ui-doaction' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('WelcomeDlg', 'Next', 'DoAction', 'TeselaFolderPrevUser', '1', 5)")
    Check 'a DoAction event (would invoke a custom action)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*disallowed control event*WelcomeDlg.Next*DoAction*')
    $path = New-Mutant 'ui-badprop' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('WelcomeDlg', 'Next', '[SecureCustomProperties]', 'x', '1', 5)")
    Check 'a dialog changes a property it must not change' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*disallowed property*SecureCustomProperties*')
    $path = New-Mutant 'ui-newdialog-missing' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('WelcomeDlg', 'Next', 'NewDialog', 'NoExisteDlg', '1', 5)")
    Check 'a NewDialog event targeting a nonexistent dialog' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*opens dialog*NoExisteDlg*does not exist*')
    $path = New-Mutant 'ui-settargetpath' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('WelcomeDlg', 'Next', 'SetTargetPath', 'ProgramMenuFolder', '1', 5)")
    Check 'SetTargetPath targets a different directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*SetTargetPath targets disallowed path*ProgramMenuFolder*')
    $path = New-Mutant 'ui-enddialog' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('WelcomeDlg', 'Next', 'EndDialog', 'Raro', '1', 5)")
    Check 'EndDialog has a value outside the allowlist' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*EndDialog has disallowed value*Raro*')
    $path = New-Mutant 'ui-scope-missing-row' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''ScopeDlg'' AND `Control_`=''Next'' AND `Argument`=''[TESELA_PREV_USER]''')
    $p = Test-MsiPackage -Path $path -ExpectedVersion $version
    Check 'missing the scope-dialog row that preserves the per-user installation directory' ((Has-Problem $p '*missing UI event*TESELA_PREV_USER*') -and (Has-Problem $p '*ScopeDlg.Next must have 9 events*'))
    $path = New-Mutant 'ui-scope-cond' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''ScopeDlg'' AND `Control_`=''Next'' AND `Argument`=''[TESELA_DEFAULT_USER]''', "INSERT INTO ``ControlEvent`` ($evCols) VALUES ('ScopeDlg', 'Next', '[INSTALLFOLDER]', '[TESELA_DEFAULT_USER]', '1', 8)")
    Check 'the per-user default-directory row would overwrite the custom directory (without a condition)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing UI event*TESELA_DEFAULT_USER*')
    $path = New-Mutant 'ui-scope-allusers' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''ScopeDlg'' AND `Control_`=''Next'' AND `Event`=''[ALLUSERS]'' AND `Argument`=''1''', "INSERT INTO ``ControlEvent`` ($evCols) VALUES ('ScopeDlg', 'Next', '[ALLUSERS]', '0', 'TESELA_SCOPE=""machine""', 1)")
    Check 'the scope dialog no longer sets ALLUSERS=1 for per-machine installs' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing UI event*ALLUSERS*')
    $path = New-Mutant 'ui-folder-notarget' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''FolderDlg'' AND `Control_`=''Next'' AND `Event`=''SetTargetPath''')
    Check 'FolderDlg.Next without SetTargetPath' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*FolderDlg.Next must call SetTargetPath*')
    $path = New-Mutant 'ui-folder-novalidate' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''FolderDlg'' AND `Control_`=''Next'' AND `Event`=''SpawnDialog''')
    Check 'FolderDlg.Next without the invalid-directory dialog' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*FolderDlg.Next must call SetTargetPath*')
    $path = New-Mutant 'ui-scope-nodisable' @('DELETE FROM `ControlCondition` WHERE `Dialog_`=''ScopeDlg'' AND `Control_`=''Next'' AND `Action`=''Disable''')
    Check 'the scope dialog allows Next even when the selected scope conflicts with an existing installation' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*ScopeDlg.Next must be disabled*')
    $path = New-Mutant 'ui-browse-prop' @('UPDATE `Control` SET `Property`=''INSTALLFOLDER'' WHERE `Dialog_`=''BrowseDlg'' AND `Control`=''DirectoryList''')
    Check 'the browse dialog uses a different property' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*BrowseDlg.DirectoryList*_BrowseProperty*')
    $path = New-Mutant 'ui-folderedit' @('UPDATE `Control` SET `Property`=''ALLUSERS'' WHERE `Dialog_`=''FolderDlg'' AND `Control`=''FolderEdit''')
    Check 'the folder field is not bound to INSTALLFOLDER' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*FolderDlg.FolderEdit must be a PathEdit on INSTALLFOLDER*')
    $path = New-Mutant 'ui-checkbox' @('UPDATE `CheckBox` SET `Value`=''2'' WHERE `Property`=''DESKTOPSHORTCUT''')
    Check 'desktop checkbox with a different value' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*CheckBox*DESKTOPSHORTCUT*')
    $path = New-Mutant 'ui-errordialog' @('UPDATE `Property` SET `Value`=''WelcomeDlg'' WHERE `Property`=''ErrorDialog''')
    Check 'ErrorDialog points to a different dialog' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*ErrorDialog*ErrorDlg*')
    $path = New-Mutant 'ui-radio-extra' @('INSERT INTO `RadioButton` (`Property`, `Order`, `Value`, `X`, `Y`, `Width`, `Height`, `Text`) VALUES (''TESELA_SCOPE'', 3, ''otro'', 0, 80, 100, 16, ''x'')')
    Check 'a third scope option' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*scope group must have the ''user'' and ''machine'' options*')
    $path = New-Mutant 'ui-eventmapping' @('INSERT INTO `EventMapping` (`Dialog_`, `Control_`, `Event`, `Attribute`) VALUES (''WelcomeDlg'', ''Body'', ''ActionText'', ''Text'')')
    Check 'an extra event subscription' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected event subscription*WelcomeDlg*')
    $path = New-Mutant 'ui-actiontext' @('INSERT INTO `ActionText` (`Action`, `Description`) VALUES (''EvilAction'', ''x'')')
    Check 'progress text for an unexpected action' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*progress text for unexpected action*EvilAction*')
    $path = New-Mutant 'ui-exit-seq' @("UPDATE ``AdminUISequence`` SET ``Sequence``=-5 WHERE ``Action``='FatalError'")
    Check 'FatalError in the wrong position in AdminUISequence (ICE20)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing FatalError at sequence -3 in AdminUISequence*')
    $path = New-Mutant 'ui-welcome-cond' @("UPDATE ``InstallUISequence`` SET ``Condition``='' WHERE ``Action``='WelcomeDlg'")
    Check 'the welcome dialog would also appear during repair or uninstall' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*WelcomeDlg in InstallUISequence has condition*')
    $path = New-Mutant 'ui-progress-late' @("UPDATE ``InstallUISequence`` SET ``Sequence``=1400 WHERE ``Action``='ProgressDlg'")
    Check 'ProgressDlg after ExecuteAction' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*ProgressDlg must run before ExecuteAction*')

    # --- m6: a registry key without a product must not create a dead end (check tesela.exe) ---------------------------------------
    $path = New-Mutant 'exe-no-locator' @('DELETE FROM `RegLocator` WHERE `Signature_`=''PrevUserExe''', 'DELETE FROM `AppSearch` WHERE `Signature_`=''PrevUserExe''', 'DELETE FROM `Signature` WHERE `Signature`=''PrevUserExe''')
    $p = Test-MsiPackage -Path $path -ExpectedVersion $version
    Check 'missing the per-user tesela.exe check' ((Has-Problem $p '*RegLocator has 5 registry searches*') -and (Has-Problem $p '*PrevUserExe*'))
    $path = New-Mutant 'exe-other-file' @('UPDATE `Signature` SET `FileName`=''otra.exe'' WHERE `Signature`=''PrevMachineExe''')
    Check 'the check searches for a different file (not tesela.exe)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Signature PrevMachineExe must search only for file tesela.exe*')
    $path = New-Mutant 'exe-minversion' @('UPDATE `Signature` SET `MinVersion`=''9.0.0'' WHERE `Signature`=''PrevUserExe''')
    Check 'the check requires a version' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*Signature PrevUserExe*')
    $path = New-Mutant 'exe-locator-type' @('UPDATE `RegLocator` SET `Type`=18 WHERE `Signature_`=''PrevUserExe''')
    Check 'tesela.exe search treats the value as raw data (would check nothing)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*expected ONE registry search PrevUserExe*type 16*')
    foreach ($a in 'TeselaStaleUser', 'TeselaStaleMachine') {
        $path = New-Mutant "stale-del-$a" @("DELETE FROM ``CustomAction`` WHERE ``Action``='$a'")
        Check "missing action $a (the orphaned key would block installation)" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*missing action $a*")
        foreach ($t2 in 'InstallExecuteSequence', 'InstallUISequence') {
            $path = New-Mutant "stale-cond-$a-$t2" @("UPDATE ``$t2`` SET ``Condition``='1' WHERE ``Action``='$a'")
            Check "$a has a different condition in $t2" (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) "*$a in $t2 has condition*")
        }
    }

    # --- m2: ALL property and EndDialog events of ALL windows are fixed ------------------------------------------------------------
    $path = New-Mutant 'ev-folder-back' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('FolderDlg', 'Back', '[INSTALLFOLDER]', 'C:" + [char]92 + "Windows" + [char]92 + "System32" + [char]92 + "', '1', 5)")
    Check 'a Back button changes INSTALLFOLDER' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected property event*FolderDlg|Back|[[]INSTALLFOLDER]*')
    $path = New-Mutant 'ev-cancel-allusers' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('CancelDlg', 'Yes', '[ALLUSERS]', '1', '1', 5)")
    Check 'a button in the cancel dialog sets ALLUSERS=1' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected property event*CancelDlg|Yes|[[]ALLUSERS]*')
    $path = New-Mutant 'ev-welcome-end' @("INSERT INTO ``ControlEvent`` ($evCols) VALUES ('WelcomeDlg', 'Next', 'EndDialog', 'Return', '1', 5)")
    Check 'EndDialog Return in the welcome dialog (would skip all dialogs)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected EndDialog*WelcomeDlg|Next|Return*')
    $path = New-Mutant 'ev-end-missing' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''ExitDialog'' AND `Control_`=''Finish'' AND `Event`=''EndDialog''')
    Check 'missing the Finish button EndDialog' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing expected EndDialog: ExitDialog|Finish|Return*')
    $path = New-Mutant 'ev-end-value' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''CancelDlg'' AND `Control_`=''No'' AND `Event`=''EndDialog''', "INSERT INTO ``ControlEvent`` ($evCols) VALUES ('CancelDlg', 'No', 'EndDialog', 'Exit', '1', 1)")
    Check 'Cancel No uses the Exit value (would still cancel)' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*unexpected EndDialog*CancelDlg|No|Exit*')
    $path = New-Mutant 'ev-folderok-cond' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''FolderDlg'' AND `Control_`=''Next'' AND `Event`=''[TESELA_FOLDER_OK]'' AND `Ordering`=4', "INSERT INTO ``ControlEvent`` ($evCols) VALUES ('FolderDlg', 'Next', '[TESELA_FOLDER_OK]', '{}', '0', 4)")
    Check 'the folder-ok flag is never cleared in a protected directory' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*missing expected property event*TESELA_FOLDER_OK*')
    $path = New-Mutant 'ev-folder-next-direct' @('DELETE FROM `ControlEvent` WHERE `Dialog_`=''FolderDlg'' AND `Control_`=''Next'' AND `Event`=''SpawnDialog''')
    Check 'Folder Next without the invalid-directory dialog' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*FolderDlg.Next must call SetTargetPath*')

    # --- B1/shield: the all-users Install button shows the UAC shield (ElevationShield) ------------------------------------------
    $path = New-Mutant 'noshield' @('UPDATE `Control` SET `Attributes`=2 WHERE `Dialog_`=''VerifyReadyDlg'' AND `Control`=''InstallElevated''')
    Check 'the per-machine Install button has no UAC shield' (Has-Problem (Test-MsiPackage -Path $path -ExpectedVersion $version) '*InstallElevated*UAC shield*')

    # --- An API error is not an empty table -----------------------------------------------------------------------------
    $m = Open-MsiDatabase $Msi
    try {
        Check 'a nonexistent table returns zero rows' (@(Get-MsiRows $m 'SELECT `Action` FROM `NoExisteTabla`' 1).Count -eq 0)
        $threw = $false
        try { Get-MsiRows $m 'SELECT `NoExiste` FROM `Property`' 1 | Out-Null } catch { $threw = $true }
        Check 'a nonexistent column is NOT treated as an empty table (throws)' $threw
        $threw = $false
        try { Get-MsiRows $m 'SELECT 1' 1 | Out-Null } catch { $threw = $true }
        Check 'a query without a table throws' $threw
    } finally { Close-Msi $m }
} finally {
    $leaf = Split-Path -Leaf $tmp
    if ($leaf -like 'tesela-test-*' -and (Split-Path -Parent $tmp) -eq [System.IO.Path]::GetTempPath().TrimEnd('\')) {
        Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# Keep the established coverage floor: deleting cases must not silently produce a green run.
$MinChecks = 198
if ($total -lt $MinChecks) { $failures.Add("only $total checks ran; expected at least $MinChecks") }
if ($failures.Count -gt 0) {
    Write-Host "msi-validate.tests: $($failures.Count) of $total checks failed:" -ForegroundColor Red
    $failures | ForEach-Object { Write-Host "  $_" }
    exit 1
}
Write-Host "msi-validate.tests: OK ($total checks)"
# EXPLICIT exit: a previous external command (dotnet, git, wix...) leaves its code in $LASTEXITCODE, and GitHub Actions (pwsh -command)
# GitHub Actions uses it as the step exit code even when everything here succeeded.
exit 0
